CalcScore(id, scope)
{
    new iKills   = GetStat(id, RPS_STAT_KILLS, scope);
    new iHead    = GetStat(id, RPS_STAT_HEADSHOTS, scope);
    new iInfect  = GetStat(id, RPS_STAT_INFECT, scope);
    new iDamage  = GetStat(id, RPS_STAT_DMG_DEALT, scope);
    new Float:flScore = iKills * get_pcvar_float(g_pCvarScoreKill)
        + iHead * get_pcvar_float(g_pCvarScoreHeadshot)
        + iInfect * get_pcvar_float(g_pCvarScoreInfect)
        + float(iDamage) / get_pcvar_float(g_pCvarScoreDamageDiv);
    return floatround(flScore, floatround_floor);
}
```
